template:
struct Point {
    ⟦x_decl⟧,
    y: i32,
}

fn shift(p: Point, dx: i32) -> Point {
    let ⟦binding⟧ = p;
    p.x += dx;
    p
}

fn main() {
    let p = Point { x: 1, y: 2 };
    let p2 = shift(p, 5);
    println!("{}, {}", p2.x, p2.y);
}

tests:
#[test]
fn shifts_point() {
    let p = Point { x: 1, y: 2 };
    let shifted = shift(p, 10);
    assert_eq!(shifted.x, 11);
    assert_eq!(shifted.y, 2);
}
